# llvm 22.1.8: from Phase 8a, the Wayland desktop (scripts/lfs/phase8a-inside.sh, pkg_llvm).
# GENERATED by convert.py; delete this line to take the recipe over by hand.
name=llvm
version=22.1.8
release=1
description="LLVM + clang"
source=(https://github.com/llvm/llvm-project/releases/download/llvmorg-22.1.8/llvm-project-22.1.8.src.tar.xz)
checksums=(md5:69065494ebcb1150b2a329c1b3db7584)
mode=tracked

build() {
  patch -Np1 -i "$srcdir/$P_LLVM"
  grep -rl '#!.*python$' | xargs sed -i '1s/python$/python3/'
  mkdir -pv /etc/clang
  for i in clang clang++; do
    echo -fstack-protector-strong > /etc/clang/$i.cfg
  done

  mkdir -v llvm/build
  cd       llvm/build
  CC=gcc CXX=g++                               \
  cmake -D CMAKE_INSTALL_PREFIX=/usr           \
        -D CMAKE_SKIP_INSTALL_RPATH=ON         \
        -D LLVM_ENABLE_FFI=ON                  \
        -D CMAKE_BUILD_TYPE=Release            \
        -D LLVM_BUILD_LLVM_DYLIB=ON            \
        -D LLVM_LINK_LLVM_DYLIB=ON             \
        -D LLVM_ENABLE_RTTI=ON                 \
        -D LLVM_TARGETS_TO_BUILD="host"        \
        -D LLVM_ENABLE_PROJECTS=clang          \
        -D LLVM_BINUTILS_INCDIR=/usr/include   \
        -D LLVM_INCLUDE_BENCHMARKS=OFF         \
        -D LLVM_INCLUDE_TESTS=OFF              \
        -D LLVM_PARALLEL_LINK_JOBS=2           \
        -D CLANG_DEFAULT_PIE_ON_LINUX=ON       \
        -D CLANG_CONFIG_FILE_SYSTEM_DIR=/etc/clang \
        -W no-author -G Ninja ..
  ninja
  ninja install
}
